// Verifies the HMAC signature from Convex over the RAW body (never re-serialized JSON).
const crypto = require('crypto');
const PATH = '/webhook/lendloop-loan-events'; // constant: the tunnel host differs from what n8n sees
const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = String(headers['x-lendloop-signature'] || '').toLowerCase();

let raw = '';
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
}

const secret = $env.LENDLOOP_TO_N8N_SECRET;
const now = Math.floor(Date.now() / 1000);
let ok = false;
let reason = 'missing';
if (secret && ts && sig && /^\d+$/.test(ts)) {
  if (Math.abs(now - Number(ts)) > 300) {
    reason = 'stale';
  } else {
    const expected = crypto.createHmac('sha256', secret).update(`${ts}.POST.${PATH}.${raw}`).digest('hex');
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(sig, 'utf8');
    ok = a.length === b.length && crypto.timingSafeEqual(a, b);
    reason = ok ? 'ok' : 'bad_signature';
  }
}
if (!ok) return [{ json: { ok: false, reason } }];

// Signed by Convex, so a malformed payload is a bug: fail loudly (error workflow + Convex retry).
const p = JSON.parse(raw);
const EVENTS = ['loan.requested', 'loan.approved', 'loan.declined', 'loan.cancelled', 'loan.returned'];
const isStr = (x) => typeof x === 'string' && x.length > 0 && x.length <= 500;
if (!isStr(p.eventId) || !isStr(p.loanId) || !EVENTS.includes(p.event) || !p.recipient ||
    !isStr(p.recipient.email) || !p.recipient.email.includes('@') || typeof p.recipient.name !== 'string' ||
    !isStr(p.toolName) || !isStr(p.startDate) || !isStr(p.endDate)) {
  throw new Error('Invalid LendLoop payload for event ' + String(p.eventId));
}
return [{ json: { ok: true, payload: p } }];

const p = $json.payload;
const oneLine = (s) => String(s).replace(/[\r\n]+/g, ' ').slice(0, 120);
const tool = oneLine(p.toolName);
const name = oneLine(p.recipient.name || 'neighbor');
const dates = `${p.startDate} to ${p.endDate}`;
const T = {
  'loan.requested': [`New request for your ${tool}`, `Someone wants to borrow your ${tool} from ${dates}. Open LendLoop to approve or decline it.`],
  'loan.approved': [`Approved: ${tool}`, `Your request to borrow ${tool} (${dates}) was approved. Contact the owner through LendLoop to pick it up.`],
  'loan.declined': [`Declined: ${tool}`, `Your request to borrow ${tool} (${dates}) was declined.`],
  'loan.cancelled': [`Request cancelled: ${tool}`, `A request to borrow your ${tool} (${dates}) was cancelled.`],
  'loan.returned': [`Return confirmed: ${tool}`, `The owner confirmed you returned ${tool}. Thanks for borrowing responsibly.`],
};
const [subject, line] = T[p.event];
return [{ json: { to: p.recipient.email, subject: '[LendLoop] ' + subject, text: `Hi ${name},\n\n${line}\n\n— LendLoop\nBorrow what you need. Lend what you don't.` } }];

const crypto = require('crypto');
function signConvex(method, path, body) {
  const ts = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', $env.N8N_TO_LENDLOOP_SECRET)
    .update(`${ts}.${method}.${path}.${body}`)
    .digest('hex');
  return { url: $env.CONVEX_SITE_URL + path, body, ts, signature };
}
const p = $('Verify HMAC').first().json.payload;
const body = JSON.stringify({
  idempotencyKey: 'notify:' + p.eventId,
  loanId: p.loanId,
  kind: 'request_notification_sent',
  detail: p.event + ' email sent',
});
return [{ json: signConvex('POST', '/api/automation-events', body) }];
